events.after:
-- Программы тренировок: библиотека упражнений, программа тренера (шаблон) и тренировки по шаблону.
-- Строка тренировки ссылается на строку шаблона: упражнение, подходы и повторы берутся из шаблона.

-- Библиотека упражнений — общая для всех тренеров
create table exercises (
  id bigint generated by default as identity primary key,
  name text not null unique
);

insert into exercises (name) values
  ('Присед'),
  ('Жим лёжа'),
  ('Тяга'),
  ('Подтягивания');

-- Программа тренера: название, например «Ноги, 4 недели»
create table programs (
  id bigint generated by default as identity primary key,
  coach_id uuid not null references profiles (id),
  title text not null
);

-- Строка шаблона: упражнение из библиотеки, подходы × повторы
create table program_items (
  id bigint generated by default as identity primary key,
  program_id bigint not null references programs (id) on delete cascade,
  exercise_id bigint not null references exercises (id),
  sets int not null check (sets > 0),
  reps int not null check (reps > 0)
);

-- Строка тренировки по шаблону — ссылка на строку шаблона. Удалили строку шаблона — удаляется и она: строк без шаблона не остаётся
create table workout_items (
  id bigint generated by default as identity primary key,
  workout_id bigint not null references workouts (id) on delete cascade,
  program_item_id bigint not null references program_items (id) on delete cascade
);

-- Подход — к строке тренировки (необязательно): удалили строку — удаляются и её подходы
alter table sets add column workout_item_id bigint references workout_items (id) on delete cascade;

-- Упражнения тренировки для страницы: упражнение, подходы и повторы — из строки шаблона.
-- security_invoker — вид читает таблицы с правами того, кто спрашивает, поэтому RLS действует так же, как на самих таблицах
create view workout_exercises with (security_invoker = true) as
  select wi.id, wi.workout_id, e.name as exercise, pi.sets, pi.reps
    from workout_items wi
    join program_items pi on pi.id = wi.program_item_id
    join exercises e on e.id = pi.exercise_id;

-- RLS на новых таблицах, как в 0002_rls.sql: политики — для вошедших (authenticated), без входа не видно ничего
alter table exercises enable row level security;
alter table programs enable row level security;
alter table program_items enable row level security;
alter table workout_items enable row level security;

-- Библиотеку видят все вошедшие
create policy "библиотека для всех" on exercises
  for select to authenticated using (true);

-- Программы и их строки: тренер видит, создаёт, меняет и удаляет свои
create policy "тренер ведёт свои программы" on programs
  for all to authenticated
  using (coach_id = auth.uid())
  with check (coach_id = auth.uid());
create policy "тренер ведёт строки программ" on program_items
  for all to authenticated
  using (program_id in (select id from programs where coach_id = auth.uid()))
  with check (program_id in (select id from programs where coach_id = auth.uid()));
-- подопечный видит программы своего тренера и их строки: из строк шаблона берутся его упражнения.
-- Через тренера, а не через workout_items: политика строк тренировок сама читает program_items, и круг политик Postgres не примет
create policy "подопечный видит программы" on programs
  for select to authenticated using (coach_id in (select coach_id from clients where user_id = auth.uid()));
create policy "подопечный видит строки шаблона" on program_items
  for select to authenticated using (program_id in (
    select p.id from programs p join clients c on c.coach_id = p.coach_id where c.user_id = auth.uid()));

-- Строки тренировок: тренер — у своих подопечных, подопечный — свои
create policy "тренер видит строки тренировок" on workout_items
  for select to authenticated using (workout_id in (
    select w.id from workouts w join clients c on c.id = w.client_id where c.coach_id = auth.uid()));
-- тренер добавляет строки в тренировки своих подопечных — и только из своих программ
create policy "тренер добавляет строки" on workout_items
  for insert to authenticated with check (
    workout_id in (
      select w.id from workouts w join clients c on c.id = w.client_id where c.coach_id = auth.uid())
    and program_item_id in (
      select pi.id from program_items pi join programs p on p.id = pi.program_id where p.coach_id = auth.uid()));
create policy "подопечный видит свои строки" on workout_items
  for select to authenticated using (workout_id in (
    select w.id from workouts w join clients c on c.id = w.client_id where c.user_id = auth.uid()));

// @vitest-environment node
// Требование: правка и удаление строки шаблона не меняют прошлые тренировки и их подходы.
// Данные тест создаёт сам — в одной транзакции, а в конце откатывает (rollback): в базе после него ничего не остаётся.
// Нужна база с миграциями и seed из supabase/, адрес — DATABASE_URL из окружения, как у test/rls.test.ts.
import { afterAll, expect, test } from "vitest";
import { pool } from "../lib/db";

// id из supabase/seed.sql: тренер Марина и прошлая тренировка её подопечной Анны — «Ноги» 19 октября
const MARINA = "11111111-1111-1111-1111-111111111111";
const LEGS = 1;

afterAll(() => pool.end());

test("правка и удаление строки шаблона не меняют прошлую тренировку и её подходы", async () => {
  const db = await pool.connect();
  // первое значение первой строки ответа: id вставленной строки или число
  const one = async (sql: string, params: unknown[]) => Object.values((await db.query(sql, params)).rows[0])[0];
  // сколько подходов записано к строке тренировки
  const setsOf = (item: unknown) => one("select count(*)::int from sets where workout_item_id = $1", [item]);
  try {
    await db.query("begin");
    // программа Марины из библиотеки: присед 3 × 10 и тяга 3 × 8
    const program = await one("insert into programs (coach_id, title) values ($1, 'Ноги') returning id", [MARINA]);
    const squat = await one(
      "insert into program_items (program_id, exercise_id, sets, reps) select $1, id, 3, 10 from exercises where name = 'Присед' returning id",
      [program],
    );
    const pull = await one(
      "insert into program_items (program_id, exercise_id, sets, reps) select $1, id, 3, 8 from exercises where name = 'Тяга' returning id",
      [program],
    );
    // назначение: строки шаблона — в тренировку Анны; к приседу — три подхода
    const item = await one("insert into workout_items (workout_id, program_item_id) values ($1, $2) returning id", [LEGS, squat]);
    await one("insert into workout_items (workout_id, program_item_id) values ($1, $2) returning id", [LEGS, pull]);
    await db.query(
      "insert into sets (workout_id, workout_item_id, weight, reps) values ($1, $2, 50, 10), ($1, $2, 50, 10), ($1, $2, 50, 10)",
      [LEGS, item],
    );

    // присед удалили из шаблона — подходы прошлой тренировки на месте
    await db.query("delete from program_items where id = $1", [squat]);
    expect(await setsOf(item), "подходов").toBe(3);

    // тягу в шаблоне заменили подтягиваниями — упражнения прежние
    await db.query("update program_items set exercise_id = (select id from exercises where name = 'Подтягивания') where id = $1", [pull]);
    const { rows } = await db.query<{ exercise: string; sets: number; reps: number }>(
      "select exercise, sets, reps from workout_exercises where workout_id = $1 order by id",
      [LEGS],
    );
    expect(rows.map((row) => `${row.exercise} — ${row.sets} × ${row.reps}`)).toEqual(["Присед — 3 × 10", "Тяга — 3 × 8"]);
  } finally {
    await db.query("rollback");
    db.release();
  }
});

import type { Metadata } from "next";
import { redirect } from "next/navigation";
import { asUser } from "@/lib/db";
import { currentUser } from "@/lib/session";
import { assignProgram, createProgram } from "./actions";

export const metadata: Metadata = { title: "Программы" };

// Страница ждёт ответа базы и отдаётся целиком, без заглушки загрузки
export const instant = false;

// Программа тренера со строками шаблона: упражнение из библиотеки, подходы × повторы; id строки из json_agg — число
type Program = { id: string; title: string; items: { id: number; exercise: string; sets: number; reps: number }[] };

// Программы вошедшего тренера, под каждой — назначение подопечному на 4 недели с даты; ниже — новая программа из библиотеки.
// Чужих программ и подопечных база не отдаст (RLS)
export default async function ProgramsPage({ searchParams }: PageProps<"/programs">) {
  const uid = await currentUser();
  if (!uid) redirect("/login");
  const { error, assigned } = await searchParams;
  const data = await asUser(uid, async (db) => {
    // программы со строками одним запросом: json_agg собирает строки шаблона в массив, у программы без строк — []
    const programs = await db.query<Program>(
      `select p.id, p.title,
              coalesce(json_agg(json_build_object('id', pi.id, 'exercise', e.name, 'sets', pi.sets, 'reps', pi.reps) order by pi.id)
                filter (where pi.id is not null), '[]') as items
         from programs p
         left join program_items pi on pi.program_id = p.id
         left join exercises e on e.id = pi.exercise_id
        where p.coach_id = $1
        group by p.id
        order by p.id`,
      [uid],
    );
    // подсказки полей: упражнения библиотеки и подопечные тренера
    const exercises = await db.query<{ id: string; name: string }>("select id, name from exercises order by id");
    const clients = await db.query<{ id: string; name: string }>(
      "select id, name from clients where coach_id = $1 order by id",
      [uid],
    );
    return { programs: programs.rows, exercises: exercises.rows, clients: clients.rows };
  });

  return (
    <main className="mx-auto w-full max-w-md p-8">
      <h1 className="text-3xl font-semibold">Программы</h1>

      {data.programs.length === 0 ? (
        <p className="mt-6 text-zinc-500">Программ пока нет</p>
      ) : (
        <ul className="mt-6 flex flex-col gap-6">
          {data.programs.map((program) => (
            <li key={program.id}>
              <h2 className="text-xl font-semibold">{program.title}</h2>
              <ul className="mt-1">
                {program.items.map((item) => (
                  <li key={item.id}>
                    {item.exercise} — {item.sets} × {item.reps}
                  </li>
                ))}
              </ul>
              {/* назначение: id программы действие получает отсюда, подопечного и дату — из формы */}
              <form action={assignProgram.bind(null, program.id)} className="mt-3 flex flex-col gap-4">
                <div className="flex flex-col gap-1">
                  <label htmlFor={`client-${program.id}`}>Подопечный</label>
                  <input
                    id={`client-${program.id}`}
                    name="client"
                    list="clients"
                    required
                    className="rounded border border-zinc-300 px-3 py-2"
                  />
                </div>
                <div className="flex flex-col gap-1">
                  <label htmlFor={`start-${program.id}`}>С даты</label>
                  <input
                    id={`start-${program.id}`}
                    name="start"
                    type="date"
                    required
                    className="rounded border border-zinc-300 px-3 py-2"
                  />
                </div>
                <button type="submit" className="rounded bg-zinc-900 px-4 py-2 text-white">
                  Назначить
                </button>
              </form>
            </li>
          ))}
        </ul>
      )}

      <form action={createProgram} className="mt-8 flex flex-col gap-4">
        <h2 className="text-xl font-semibold">Новая программа</h2>
        <div className="flex flex-col gap-1">
          <label htmlFor="title">Название</label>
          <input id="title" name="title" required className="rounded border border-zinc-300 px-3 py-2" />
        </div>
        <div className="flex flex-col gap-1">
          <label htmlFor="exercise">Упражнение</label>
          <input
            id="exercise"
            name="exercise"
            list="exercises"
            required
            className="rounded border border-zinc-300 px-3 py-2"
          />
        </div>
        <div className="flex flex-col gap-1">
          <label htmlFor="sets">Подходы</label>
          <input id="sets" name="sets" inputMode="numeric" required className="rounded border border-zinc-300 px-3 py-2" />
        </div>
        <div className="flex flex-col gap-1">
          <label htmlFor="reps">Повторы</label>
          <input id="reps" name="reps" inputMode="numeric" required className="rounded border border-zinc-300 px-3 py-2" />
        </div>
        <button type="submit" className="rounded bg-zinc-900 px-4 py-2 text-white">
          Создать
        </button>
      </form>

      {/* подсказки для полей «Упражнение» и «Подопечный» */}
      <datalist id="exercises">
        {data.exercises.map((exercise) => (
          <option key={exercise.id} value={exercise.name} />
        ))}
      </datalist>
      <datalist id="clients">
        {data.clients.map((client) => (
          <option key={client.id} value={client.name} />
        ))}
      </datalist>

      {/* после назначения — сколько тренировок назначено (число — в адресе) */}
      {typeof assigned === "string" && (
        <p role="status" className="mt-4 text-green-700">
          Назначено тренировок: {assigned}
        </p>
      )}
      {typeof error === "string" && (
        <p role="alert" className="mt-4 text-red-600">
          {error}
        </p>
      )}
    </main>
  );
}

"use server";

import { redirect } from "next/navigation";
import { asUser } from "@/lib/db";
import { currentUser } from "@/lib/session";

// Программа назначается на 4 недели: тренировка раз в неделю
const WEEKS = 4;

// Ошибку страница покажет под формами: её текст — в адресе
const fail = (error: string) => `/programs?error=${encodeURIComponent(error)}`;

// Целое число больше нуля из поля формы, иначе null
function positive(value: FormDataEntryValue | null): number | null {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

// Тренер создаёт программу: название и строка шаблона — упражнение из библиотеки, подходы × повторы.
// Запрос идёт от имени тренера: программа записывается ему (coach_id = uid), в чужую программу строку не даст вставить RLS.
export async function createProgram(form: FormData) {
  const uid = await currentUser();
  if (!uid) redirect("/login");
  const title = String(form.get("title") ?? "").trim();
  const exercise = String(form.get("exercise") ?? "").trim();
  const sets = positive(form.get("sets"));
  const reps = positive(form.get("reps"));
  if (title === "") redirect(fail("Нужно название программы"));
  if (sets === null || reps === null) redirect(fail("Подходы и повторы — целые числа больше нуля"));

  const created = await asUser(uid, async (db) => {
    const found = await db.query<{ id: string }>("select id from exercises where name = $1", [exercise]);
    if (found.rows.length === 0) return false;
    const program = await db.query<{ id: string }>(
      "insert into programs (coach_id, title) values ($1, $2) returning id",
      [uid, title],
    );
    await db.query("insert into program_items (program_id, exercise_id, sets, reps) values ($1, $2, $3, $4)", [
      program.rows[0].id,
      found.rows[0].id,
      sets,
      reps,
    ]);
    return true;
  });
  if (!created) redirect(fail("Такого упражнения нет в библиотеке"));
  redirect("/programs");
}

// Тренер назначает программу programId подопечному на 4 недели: тренировка раз в неделю с даты из формы, название — как у программы.
// В каждую тренировку — строки шаблона; упражнение, подходы и повторы база кладёт в них копией (0005_programs_copy.sql),
// поэтому правка и удаление шаблона назначенное не тронут. Подопечный — по имени среди подопечных тренера; чужого не отдаст RLS.
export async function assignProgram(programId: string, form: FormData) {
  const uid = await currentUser();
  if (!uid) redirect("/login");
  const name = String(form.get("client") ?? "").trim();
  const start = String(form.get("start") ?? "");
  // дата начала — ГГГГ-ММ-ДД из поля даты: даты тренировок идут от неё, а не от сегодняшнего дня
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start)) redirect(fail("Нужна дата начала"));

  const error = await asUser(uid, async (db) => {
    const clients = await db.query<{ id: string }>("select id from clients where coach_id = $1 and name = $2", [uid, name]);
    if (clients.rows.length === 0) return "Нет такого подопечного";
    if (clients.rows.length > 1) return "Подопечных с таким именем несколько";
    const program = await db.query<{ title: string }>("select title from programs where id = $1", [programId]);
    if (program.rows.length === 0) return "Программа не найдена";
    for (let week = 0; week < WEEKS; week++) {
      // день тренировки считает база: дата начала + 7 дней × неделя
      const workout = await db.query<{ id: string }>(
        "insert into workouts (client_id, title, day) values ($1, $2, $3::date + 7 * $4::int) returning id",
        [clients.rows[0].id, program.rows[0].title, start, week],
      );
      await db.query(
        "insert into workout_items (workout_id, program_item_id) select $1, id from program_items where program_id = $2 order by id",
        [workout.rows[0].id, programId],
      );
    }
    return null;
  });
  if (error) redirect(fail(error));
  // страница подтвердит назначение: «Назначено тренировок: 4»
  redirect(`/programs?assigned=${WEEKS}`);
}

